insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$atibaia$q$, $q$https://prefeitura.atibaia.sp.gov.br/imprensa/pdf/2012/1354.pdf (Dec. 6.667/2012, IOE nº 1354, p. 13) ; https://prefeitura.atibaia.sp.gov.br/imprensa/pdf/2022/2491_38cc50d246e3956dd051990e35b2bf10.pdf (Dec. 10.197/2022, art. 52)$q$, $q$Atos oficiais de Atibaia: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: derivada do OpenStreetMap (ODbL 1.0, © colaboradores do OSM): vias recortadas pelo perímetro do quadrilátero montado com as próprias vias do OSM.$q$, 56, $q$Regra principal: Dec. 6.667/2012 (Quadrilátero de Restrição de Trânsito de Veículos Pesados, centro), caminhão maior que o VUC local proibido seg–sex 9h–18h e sáb 9h–14h, livre domingos e feriados. Desativadas: LC 470/2005, art. 5º (APE do Centro Histórico, > 6 t; vigência incerta e sem geometria) e duas pistas sem ato (Estrada dos Pires, Al. Prof. Lucas Nogueira Garcez).$q$);
